import{_ as a,o as e,c as l,a2 as r}from"./chunks/framework.DXRWYp4X.js";const g=JSON.parse('{"title":"23 · 项目实操册：两个旗舰 + 评估与安全","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://R2h1.github.io/fullstack-learning-site/23-项目实操册"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"23 · 项目实操册：两个旗舰 + 评估与安全 | 全栈 × AI 学习路径"}],["meta",{"property":"og:description","content":"面试级 · 生产级 · 企业级的全栈 + AI 学习课程（个人笔记，内容优先）"}],["meta",{"property":"og:url","content":"https://R2h1.github.io/fullstack-learning-site/23-项目实操册"}],["meta",{"name":"twitter:card","content":"summary"}]]},"headers":[],"relativePath":"23-项目实操册.md","filePath":"23-项目实操册.md","lastUpdated":1793294125000}'),i={name:"23-项目实操册.md"};function o(d,t,n,s,h,c){return e(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="_23-·-项目实操册-两个旗舰-评估与安全" tabindex="-1">23 · 项目实操册：两个旗舰 + 评估与安全 <a class="header-anchor" href="#_23-·-项目实操册-两个旗舰-评估与安全" aria-label="Permalink to &quot;23 · 项目实操册：两个旗舰 + 评估与安全&quot;">​</a></h1><blockquote><p>达标目标：<strong>交付两个能扛住三十分钟追问的旗舰项目（高并发 SaaS 后端、生产级 RAG），并给 RAG 配上企业级评估体系与安全护栏。</strong> 一句话理由：项目不是「功能清单」，是「数字 + 故障 + 取舍」的证据链；面试官见过一百个 todo app，没见过一个能讲清 P99 从 800ms 优化到 120ms 的人。 衔接：20 章（排期与验收物 2/3）、06–13 章（后端全部知识在此变现）、15/16 章（RAG 链路）、21/22 章（项目二反哺两把长矛）。 ⚠️ 操练册：每节以「部署成功 / 数字入表 / 报告入库」为完成标志。</p></blockquote><hr><h2 id="_1-项目一-高并发-saas-后端-第-2–6-个月" tabindex="-1">1. 项目一：高并发 SaaS 后端（第 2–6 个月） <a class="header-anchor" href="#_1-项目一-高并发-saas-后端-第-2–6-个月" aria-label="Permalink to &quot;1. 项目一：高并发 SaaS 后端（第 2–6 个月）&quot;">​</a></h2><p><strong>一句话定位</strong>：多租户任务管理 SaaS 的后端，真实公开上线，自己运营到 50+ 活跃用户。</p><h3 id="_1-1-范围裁剪-做之前先写一页纸" tabindex="-1">1.1 范围裁剪（做之前先写一页纸） <a class="header-anchor" href="#_1-1-范围裁剪-做之前先写一页纸" aria-label="Permalink to &quot;1.1 范围裁剪（做之前先写一页纸）&quot;">​</a></h3><ul><li>做：注册/登录（邮箱+OAuth2 之一）、团队/租户模型、任务 CRUD、操作审计日志、webhook 出站、限流、Docker 部署</li><li>不做：支付、复杂前端（拿现成 UI 模板或纯 API + 一个极简页面）、移动端</li><li>裁剪原则：每个「做」都要能撑起一组面试追问；「不做」写清为什么不做（这本身就是取舍证据）</li></ul><h3 id="_1-2-技术栈与硬指标-对齐-20-章选型" tabindex="-1">1.2 技术栈与硬指标（对齐 20 章选型） <a class="header-anchor" href="#_1-2-技术栈与硬指标-对齐-20-章选型" aria-label="Permalink to &quot;1.2 技术栈与硬指标（对齐 20 章选型）&quot;">​</a></h3><ul><li>NestJS + Prisma + PostgreSQL + Redis + BullMQ（第 22 章造完 minimq 后，可换回工业品，面试讲「造过再用，知道它为什么这么设计」）</li><li>Docker 多阶段构建 + GitHub Actions CI/CD + 云上单实例起步（阶段一再上不复杂的高可用，别一开始就 K8s）</li><li>上线即埋：结构化日志 + 请求 traceId + Prometheus 指标 + 告警底线（对位 10 章）</li><li><strong>硬指标</strong>：公开接口 P99 &lt; 300ms（无 AI 调用）；单位成本可计算（$/百次请求）</li></ul><h3 id="_1-3-按周里程碑" tabindex="-1">1.3 按周里程碑 <a class="header-anchor" href="#_1-3-按周里程碑" aria-label="Permalink to &quot;1.3 按周里程碑&quot;">​</a></h3><table tabindex="0"><thead><tr><th>周</th><th>交付</th><th>章节回填</th></tr></thead><tbody><tr><td>1–2</td><td>项目骨架 + CI + 部署流水线跑通</td><td>10</td></tr><tr><td>3–4</td><td>认证（JWT 双 token + 刷新 + RBAC）</td><td>08</td></tr><tr><td>5–6</td><td>多租户数据模型 + 任务 CRUD + 审计</td><td>09/11</td></tr><tr><td>7</td><td>Redis 缓存层 + 限流（令牌桶）</td><td>12</td></tr><tr><td>8–9</td><td>webhook 出站队列（重试+死信+幂等）</td><td>09/12</td></tr><tr><td>10</td><td>公开上线 + 找 20 个真实用户（社群/朋友/小红书/即刻都行）</td><td>—</td></tr><tr><td>11–12</td><td><strong>故障日</strong>：压测打出真实瓶颈 → 优化 → 复盘文档</td><td>05/10/11/13</td></tr></tbody></table><h3 id="_1-4-「故障日」怎么做-这是项目一的灵魂" tabindex="-1">1.4 「故障日」怎么做（这是项目一的灵魂） <a class="header-anchor" href="#_1-4-「故障日」怎么做-这是项目一的灵魂" aria-label="Permalink to &quot;1.4 「故障日」怎么做（这是项目一的灵魂）&quot;">​</a></h3><ol><li>用 vegeta/k6 压到 P99 崩坏或依赖过载（连接池打满/N+1 现形/缓存击穿都行）</li><li>走完整排查：指标 → 日志 → 火焰图/慢查询 → 定位 → 修复 → 复压验证</li><li>产出 <code>incident-report.md</code>：时间线、根因、修复、防复发（监控项/压测纳入 CI）</li><li>面试叙事直接可用：「我排查过的生产问题」不再虚构</li></ol><h3 id="_1-5-验收清单-全勾才算交付" tabindex="-1">1.5 验收清单（全勾才算交付） <a class="header-anchor" href="#_1-5-验收清单-全勾才算交付" aria-label="Permalink to &quot;1.5 验收清单（全勾才算交付）&quot;">​</a></h3><ul><li>[ ] 公网地址 + 真实用户 ≥50（留存截图）</li><li>[ ] 三组数字：峰值 QPS、P99、单位成本（带监控截图）</li><li>[ ] 一份故障复盘（含前后对比数据）</li><li>[ ] 架构图一张（数据流 + 故障模式标注，面试白板素材）</li></ul><h2 id="_2-项目二-生产级-rag-系统-第-8–15-个月" tabindex="-1">2. 项目二：生产级 RAG 系统（第 8–15 个月） <a class="header-anchor" href="#_2-项目二-生产级-rag-系统-第-8–15-个月" aria-label="Permalink to &quot;2. 项目二：生产级 RAG 系统（第 8–15 个月）&quot;">​</a></h2><p><strong>一句话定位</strong>：垂直领域文档问答（选你熟的：门窗报价规则/某合规文档/开源项目 wiki），带评估报告与安全护栏，前端复用你的 4 年优势（流式 UI + 引用展示）。</p><h3 id="_2-1-范围" tabindex="-1">2.1 范围 <a class="header-anchor" href="#_2-1-范围" aria-label="Permalink to &quot;2.1 范围&quot;">​</a></h3><ul><li>摄入：真实文档集 500+ 篇/页（自己造数据是新手项目特征），chunk 策略三档对照实验</li><li>检索：pgvector 向量 + PostgreSQL FTS 关键词，RRF 混合 + rerank（bge-reranker）</li><li>生成：流式 + 引用溯源 + 「不知道」兜底；结构化输出走 schema 校验</li><li>服务：Python FastAPI（与 21 章 vLLM 部署对接，模型用 7B 级 + API 双轨，成本可控）</li><li>评估与安全：见 2.3/2.4，<strong>这是与「demo 玩家」的分水岭，优先级高于一切新功能</strong></li></ul><h3 id="_2-2-里程碑-骨架期-细节随执行展开" tabindex="-1">2.2 里程碑（骨架期，细节随执行展开） <a class="header-anchor" href="#_2-2-里程碑-骨架期-细节随执行展开" aria-label="Permalink to &quot;2.2 里程碑（骨架期，细节随执行展开）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>期</th><th>交付</th></tr></thead><tbody><tr><td>M1</td><td>摄入 + 向量检索 + 生成全链路（无评估，先能用）</td></tr><tr><td>M2</td><td>建 golden set（≥80 条，含难例）→ Recall@k / MRR / Faithfulness 基线报告</td></tr><tr><td>M3</td><td>优化循环：chunk/混合检索/rerank 各跑一组对照，<strong>出优化前后对比图</strong></td></tr><tr><td>M4</td><td>Langfuse 全量 trace + 成本看板 + 语义缓存上线</td></tr><tr><td>M5</td><td>安全：prompt 注入红队自测（2.4 清单）+ PII 脱敏 + 输出过滤，出红队报告</td></tr><tr><td>M6</td><td>20 个真实用户内测 + 一次「badcase 排障」完整复盘（面试黄金素材）</td></tr></tbody></table><h3 id="_2-3-评估工程-企业级-ai-的核心壁垒位" tabindex="-1">2.3 评估工程（企业级 AI 的核心壁垒位） <a class="header-anchor" href="#_2-3-评估工程-企业级-ai-的核心壁垒位" aria-label="Permalink to &quot;2.3 评估工程（企业级 AI 的核心壁垒位）&quot;">​</a></h3><ul><li><strong>Golden set</strong>：80–200 条「问题 → 期望出处 → 参考答案」三层标注；从真实 badcase 持续追加（评估集是活的）</li><li><strong>检索指标</strong>：Recall@k、MRR、nDCG；每个检索改动必须跑基线（CI 里跑，对位 04 章「AI 产出要有 CI 护栏」的思路用在 AI 功能上）</li><li><strong>生成指标</strong>：Faithfulness（回答是否只基于检索内容）、Answer Relevance；LLM-as-Judge 实现 + 抽样人工校准（知道 judge 的偏差方向：位置偏好、冗长偏好、自偏好）</li><li><strong>在线评估</strong>：Langfuse trace 采样打分 + 用户反馈信号回流 golden set</li><li>工具二选一实操即可：<strong>RAGAS</strong>（指标库）+ <strong>Langfuse</strong>（trace/评估运营）</li></ul><p><strong>必会</strong>：讲一次「指标变好但体验变差」的陷阱及校准方法；给「幻觉」下可测量的定义。</p><h3 id="_2-4-安全与护栏-对标-owasp-llm-top-10" tabindex="-1">2.4 安全与护栏（对标 OWASP LLM Top 10） <a class="header-anchor" href="#_2-4-安全与护栏-对标-owasp-llm-top-10" aria-label="Permalink to &quot;2.4 安全与护栏（对标 OWASP LLM Top 10）&quot;">​</a></h3><ul><li>注入纵深防御（从外到内）：输入预分类 → 指令/数据分离标记 → 工具白名单 + 参数校验 → 输出过滤 → 高危动作人在环中</li><li>PII：摄入期 NER 识别 + 存储脱敏 + 输出期正则兜底</li><li>数据投毒：文档来源分级，不可信来源进检索要打标并可被策略过滤</li><li>红队自测清单：直接注入/间接注入（文档内埋指令）/越狱/工具滥用/DoS（超长上下文），每条留用例进回归集</li><li>成本攻击面：语义缓存 + 用户级 token 预算 + 限流（对位 09 章）</li></ul><h3 id="_2-5-验收清单" tabindex="-1">2.5 验收清单 <a class="header-anchor" href="#_2-5-验收清单" aria-label="Permalink to &quot;2.5 验收清单&quot;">​</a></h3><ul><li>[ ] 评估报告：基线 + 三轮优化前后对比（图，不是表）</li><li>[ ] 红队报告：5 类攻击面用例与结论</li><li>[ ] 成本账单：月度 token 支出 + 缓存命中率 + 单请求成本</li><li>[ ] 真实用户反馈记录 ≥20 条 + 一次 badcase 复盘文档</li><li>[ ] 前端证据：流式 + 引用 + 中断的完整体验录屏</li></ul><h2 id="_3-两项目共用的包装标准-d3→简历" tabindex="-1">3. 两项目共用的包装标准（D3→简历） <a class="header-anchor" href="#_3-两项目共用的包装标准-d3→简历" aria-label="Permalink to &quot;3. 两项目共用的包装标准（D3→简历）&quot;">​</a></h2><p>每个项目交付四件套：<strong>README（30 秒讲清定位与数字）→ 架构图（含故障模式标注）→ 复盘文档（故障/badcase 各一）→ demo 录屏（2 分钟）</strong>。写不出这四件套，等于没做完。面试叙事按 18 章 STAR 框架填，但素材全部来自上述文档，不即兴。</p><h2 id="_4-达标标准" tabindex="-1">4. 达标标准 <a class="header-anchor" href="#_4-达标标准" aria-label="Permalink to &quot;4. 达标标准&quot;">​</a></h2><p><strong>L3：</strong></p><ul><li>[ ] 项目一验收清单全绿；能白板讲架构 + 故障定位路径</li><li>[ ] 项目二 M1–M4 完成，评估基线与优化对比可展示</li></ul><p><strong>D4：</strong></p><ul><li>[ ] 项目二评估体系 + 红队报告达到「给同行 review 不丢人」水平</li><li>[ ] 两项目四件套入库，且至少 1 篇项目深度文发布（素材进 24 章）</li></ul>',35)])])}const b=a(i,[["render",o]]);export{g as __pageData,b as default};
